package com.jnapanam.sportszone.training.model;
import com.jnapanam.sportszone.catalog.model.Sport; import jakarta.persistence.*; import java.time.Instant; import java.util.*;
@Entity @Table(name="training_programs") public class TrainingProgram{
 @Id private UUID id;@Column(nullable=false,unique=true,length=40)private String code;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="sport_id")private Sport sport;@Column(nullable=false,length=140)private String name;@Column(length=700)private String description;@Column(name="min_age")private Integer minAge;@Column(name="max_age")private Integer maxAge;@Enumerated(EnumType.STRING)@Column(nullable=false,length=30)private TrainingLevel level;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private TrainingStatus status;@Column(name="created_at",nullable=false)private Instant createdAt;@Column(name="updated_at",nullable=false)private Instant updatedAt;
 protected TrainingProgram(){}public TrainingProgram(String code,Sport sport,String name,String description,Integer minAge,Integer maxAge,TrainingLevel level){id=UUID.randomUUID();this.code=code.trim().toUpperCase(Locale.ROOT);update(sport,name,description,minAge,maxAge,level);status=TrainingStatus.ACTIVE;createdAt=Instant.now();updatedAt=createdAt;}public void update(Sport sport,String name,String description,Integer minAge,Integer maxAge,TrainingLevel level){this.sport=sport;this.name=name.trim();this.description=description==null||description.isBlank()?null:description.trim();this.minAge=minAge;this.maxAge=maxAge;this.level=level;updatedAt=Instant.now();}public void status(TrainingStatus s){status=s;updatedAt=Instant.now();}
 public UUID getId(){return id;}public String getCode(){return code;}public Sport getSport(){return sport;}public String getName(){return name;}public String getDescription(){return description;}public Integer getMinAge(){return minAge;}public Integer getMaxAge(){return maxAge;}public TrainingLevel getLevel(){return level;}public TrainingStatus getStatus(){return status;}
}
